#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> nums = {5, 2, 8, 1, 9, 3};
    std::sort(nums.begin(), nums.end());
    std::cout << nums[0] << "\n";
    std::cout << nums[nums.size()-1] << "\n";
    std::cout << nums[0] << "\n";
    return 0;
}
